#!/usr/bin/env node
// Desktop release version consistency.
//
// A release bump has to land in four places. Three of them are edited by hand
// and one (Cargo.lock) is regenerated by cargo, so it is the one that gets
// forgotten: v1.5.0 and v1.5.1 both shipped with a stale lockfile and needed a
// follow-up commit each time. A stale lockfile is not a build failure - cargo
// silently rewrites it - so nothing catches it until someone reads the diff.
//
// Exits non-zero listing every file that disagrees.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const CRATE_NAME = 'junqi-desktop';

const read = (relative) => readFileSync(new URL(`../${relative}`, import.meta.url), 'utf8');

/** The version cargo recorded for this crate inside the lockfile. */
export function lockfileCrateVersion(lockfile, crateName = CRATE_NAME) {
  const packages = lockfile.split(/^\[\[package\]\]$/m);
  for (const block of packages) {
    const name = /^\s*name\s*=\s*"([^"]+)"/m.exec(block)?.[1];
    if (name !== crateName) continue;
    const version = /^\s*version\s*=\s*"([^"]+)"/m.exec(block)?.[1];
    if (version) return version;
  }
  return null;
}

export function cargoManifestVersion(manifest) {
  const packageSection = manifest.split(/^\[/m).find((block) => block.startsWith('package]'));
  return /^\s*version\s*=\s*"([^"]+)"/m.exec(packageSection ?? '')?.[1] ?? null;
}

export function collectReleaseVersions(sources) {
  return [
    { file: 'package.json', version: JSON.parse(sources.packageJson).version ?? null },
    { file: 'src-tauri/Cargo.toml', version: cargoManifestVersion(sources.cargoToml) },
    { file: 'src-tauri/tauri.conf.json', version: JSON.parse(sources.tauriConf).version ?? null },
    { file: 'src-tauri/Cargo.lock', version: lockfileCrateVersion(sources.cargoLock) },
  ];
}

/** Returns a human-readable failure, or null when every source agrees. */
export function describeVersionMismatch(entries) {
  const missing = entries.filter((entry) => !entry.version);
  if (missing.length > 0) {
    return `Could not read a version from: ${missing.map((entry) => entry.file).join(', ')}`;
  }
  const distinct = [...new Set(entries.map((entry) => entry.version))];
  if (distinct.length === 1) return null;
  const detail = entries.map((entry) => `  ${entry.version.padEnd(12)} ${entry.file}`).join('\n');
  return `Desktop release version is not consistent across all four sources:\n${detail}`;
}

export function checkReleaseVersionConsistency() {
  return describeVersionMismatch(collectReleaseVersions({
    packageJson: read('package.json'),
    cargoToml: read('src-tauri/Cargo.toml'),
    tauriConf: read('src-tauri/tauri.conf.json'),
    cargoLock: read('src-tauri/Cargo.lock'),
  }));
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const failure = checkReleaseVersionConsistency();
  if (failure) {
    console.error(failure);
    console.error('\nRun `cargo check` (or `cargo update -p junqi-desktop`) in src-tauri/ after bumping the version.');
    process.exit(1);
  }
  const [{ version }] = collectReleaseVersions({
    packageJson: read('package.json'),
    cargoToml: read('src-tauri/Cargo.toml'),
    tauriConf: read('src-tauri/tauri.conf.json'),
    cargoLock: read('src-tauri/Cargo.lock'),
  });
  console.log(`PASS Desktop release version consistent across four sources: ${version}`);
}
